CREATE TABLE IF NOT EXISTS roles (id VARCHAR(30) PRIMARY KEY, name VARCHAR(80) NOT NULL, permissions VARCHAR(600) NOT NULL);
CREATE TABLE IF NOT EXISTS app_users (id VARCHAR(36) PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role_id VARCHAR(30) NOT NULL, FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS members (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, phone VARCHAR(11) NOT NULL UNIQUE, level VARCHAR(20) NOT NULL, balance_cents BIGINT NOT NULL DEFAULT 0, points BIGINT NOT NULL DEFAULT 0, status VARCHAR(16) NOT NULL DEFAULT '正常', note VARCHAR(500) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (balance_cents >= 0), CHECK (points >= 0));
CREATE TABLE IF NOT EXISTS transactions (id VARCHAR(36) PRIMARY KEY, member_id VARCHAR(36) NOT NULL, type VARCHAR(16) NOT NULL, amount_cents BIGINT NOT NULL, before_cents BIGINT NOT NULL, after_cents BIGINT NOT NULL, points_delta BIGINT NOT NULL, channel VARCHAR(30) NOT NULL, note VARCHAR(500) NOT NULL, operator_name VARCHAR(80) NOT NULL, request_key VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (member_id) REFERENCES members(id), CHECK (amount_cents > 0));
CREATE TABLE IF NOT EXISTS audit_logs (id VARCHAR(36) PRIMARY KEY, action VARCHAR(80) NOT NULL, target_id VARCHAR(100) NOT NULL, detail VARCHAR(1000) NOT NULL, operator_name VARCHAR(80) NOT NULL, result VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS revoked_tokens (token_id VARCHAR(100) PRIMARY KEY, expires_at TIMESTAMP NOT NULL);
